const activeUnitRate=(u,date='')=>{const d=date||iso(new Date());const rows=(state.unitRates||[]).filter(r=>String(r.unit_id)===String(u?.id)&&r.active!==false&&(!r.valid_from||r.valid_from<=d)&&(!r.valid_to||r.valid_to>=d)).sort((a,b)=>String(b.valid_from||'').localeCompare(String(a.valid_from||'')));return rows[0]||null};
