function showModal(title,html,actions=''){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modalActions').innerHTML=actions||'<button class="secondary-btn" id="modalCancel">Închide</button>';$('modalBackdrop').classList.remove('hidden');const c=$('modalCancel');if(c)c.onclick=closeModal}
