    const lanes=Math.max(1,laneEnds.length),verticalZoom=Math.max(.72,Math.min(1.65,state.zoom)),laneStep=32*verticalZoom,rowHeight=Math.max(54*verticalZoom,20*verticalZoom+lanes*laneStep);
