  document.querySelectorAll('[data-room-location]').forEach(b=>b.onclick=e=>{if(e.target.closest('[data-edit-location]'))return;state.roomLocationFocus=b.dataset.roomLocation;renderRooms();setTimeout(()=>document.querySelector('.hierarchy-rooms')?.scrollIntoView({behavior:'smooth',block:'start'}),20)});
  document.querySelectorAll('[data-edit-site]').forEach(b=>b.onclick=e=>{e.stopPropagation();openMasterEditor('sites',b.dataset.editSite)});
  document.querySelectorAll('[data-edit-location]').forEach(b=>b.onclick=e=>{e.stopPropagation();openMasterEditor('locations',b.dataset.editLocation)});
