function openStayEditor(id){const s=state.stays.find(x=>String(x.id)===String(id));showModal('Editare cazare',stayForm(s),'<button class="secondary-btn" id="modalCancel">Anulează</button><button class="primary-btn" id="saveStayBtn">Salvează</button>');$('modalCancel').onclick=closeModal;$('saveStayBtn').onclick=async()=>{const f=new FormData($('stayForm')),changes=Object.fromEntries(f.entries());changes.billing_rate_amount=changes.billing_rate_amount===''?null:Number(changes.billing_rate_amount);changes.billing_share_percent=Number(changes.billing_share_percent||100);if(changes.check_out_date<=changes.check_in_date)return toast('Check-out trebuie să fie după check-in','error');await saveStay(s.id,changes,'Cazarea a fost actualizată');closeModal()}}
function openNewStay(unitId='',personId=''){showModal('Cazare nouă',stayForm({unit_id:unitId,person_id:personId,status:'planned'}),'<button class="secondary-btn" id="modalCancel">Anulează</button><button class="primary-btn" id="createStayBtn">Salvează cazarea</button>');$('modalCancel').onclick=closeModal;$('createStayBtn').onclick=async()=>{const f=Object.fromEntries(new FormData($('stayForm')).entries());f.billing_rate_amount=f.billing_rate_amount===''?null:Number(f.billing_rate_amount);f.billing_share_percent=Number(f.billing_share_percent||100);if(f.check_out_date<=f.check_in_date)return toast('Check-out trebuie să fie după check-in','error');try{let personId=f.person_id,unitId=f.unit_id,siteId=null;if(!personId){if(!f.new_person_name.trim())return toast('Selectează o persoană sau completează numele nou','error');const person=await SiteFlowApi.createPerson({full_name:f.new_person_name.trim(),company_name:f.new_person_company.trim()||null,person_type:'worker',status:'active',active:true});state.people.push(person);personId=person.id}if(!unitId){if(!f.new_location_name.trim()||!f.new_room_name.trim())return toast('Completează locația și camera nouă','error');if(f.new_site_name.trim()){try{const site=await SiteFlowApi.createSite({name:f.new_site_name.trim(),status:'active',active:true});state.sites.push(site);siteId=site.id}catch(err){console.warn('Șantierul nu a putut fi creat:',err.message)}}const location=await SiteFlowApi.createLocation({name:f.new_location_name.trim(),city:f.new_location_name.trim(),address:f.new_location_address.trim()||f.new_location_name.trim(),country:'Germany',location_type:'apartment',status:'active',active:true,site_id:siteId||null});state.locations.push(location);const unit=await SiteFlowApi.createUnit({location_id:location.id,name:f.new_room_name.trim(),unit_type:'room',capacity:Number(f.new_room_capacity||1),beds_count:Number(f.new_room_capacity||1),status:'active',active:true,nightly_cost:f.new_room_cost?Number(f.new_room_cost):null});state.units.push(unit);unitId=unit.id}const payload={person_id:personId,unit_id:unitId,site_id:siteId||null,check_in_date:f.check_in_date,check_out_date:f.check_out_date,status:f.status||'planned',stay_type:'standard',notes:f.notes||null,billing_rate_type:f.billing_rate_type||'per_person_per_night',billing_rate_amount:f.billing_rate_amount,billing_share_percent:f.billing_share_percent};const created=await SiteFlowApi.createStay(payload);state.stays.push(created);fillLocations();renderHousing();closeModal();toast('Cazarea și datele noi au fost salvate')}catch(e){toast(`Nu s-a putut salva: ${e.message}`,'error')}}}
