  const total=rows.reduce((q,r)=>q+r.total,0),active=rows.filter(r=>barTone(r.st)==='active').reduce((q,r)=>q+r.total,0),locs=new Set(rows.map(r=>r.l.id)).size,persons=new Set(rows.map(r=>r.st.person_id)).size,byLoc={},byMonth={};
