function showRateEditor(){const typeOptions=[['per_person_per_night','Persoană / noapte'],['per_bed_per_night','Pat / noapte'],['per_room_per_night','Cameră / noapte'],['per_room_per_month','Cameră / lună']];showModal('Tarife camere',`<div class="rate-editor rate-editor-complete">${state.units.map(u=>{const l=state.locations.find(x=>x.id===u.location_id),rate=activeUnitRate(u),type=roomRateType(u),amount=roomRate(u);return`<div class="rate-row" data-rate-row="${u.id}"><span><b>${esc(locName(l))} · ${esc(u.name||'Cameră')}</b><small>${esc(l?.address||'')}</small></span><select data-rate-type="${u.id}">${typeOptions.map(([v,t])=>`<option value="${v}" ${type===v?'selected':''}>${t}</option>`).join('')}</select><input type="number" min="0" step="0.01" data-rate-amount="${u.id}" value="${amount||''}" placeholder="Tarif EUR"><input type="date" data-rate-from="${u.id}" value="${rate?.valid_from||iso(new Date())}"></div>`}).join('')}</div>`,'<button class="secondary-btn" id="modalCancel">Anulează</button><button class="primary-btn" id="saveRatesBtn">Salvează tarifele</button>');$('modalBackdrop').querySelector('.modal').classList.add('wide');$('modalCancel').onclick=closeModal;$('saveRatesBtn').onclick=async()=>{try{for(const row of document.querySelectorAll('[data-rate-row]')){const unitId=row.dataset.rateRow,u=state.units.find(x=>String(x.id)===String(unitId)),existing=activeUnitRate(u),type=row.querySelector('[data-rate-type]').value,amount=Number(row.querySelector('[data-rate-amount]').value||0),validFrom=row.querySelector('[data-rate-from]').value||iso(new Date());const saved=await SiteFlowApi.saveUnitRate(unitId,{rate_type:type,amount,valid_from:validFrom,currency:'EUR'},existing?.id||null);const idx=state.unitRates.findIndex(x=>String(x.id)===String(saved.id));if(idx>=0)state.unitRates[idx]=saved;else state.unitRates.push(saved);if(type==='per_room_per_night'){const updated=await SiteFlowApi.updateUnit(unitId,{nightly_cost:amount});Object.assign(u,updated)}}closeModal();renderDashboard();renderHousing();toast('Tarifele complete au fost salvate')}catch(e){toast(`Tarifele nu au fost salvate: ${e.message}`,'error')}}}
