function renderReportsPageLegacy(){const lm=Object.fromEntries(state.locations.map(x=>[x.id,x])),um=Object.fromEntries(state.units.map(x=>[x.id,x])),pm=Object.fromEntries(state.people.map(x=>[x.id,x]));const dates=state.stays.flatMap(s=>[s.check_in_date,s.check_out_date]).filter(Boolean).sort();const from=dates[0]||iso(new Date()),to=dates.at(-1)||iso(new Date());showModal('Rapoarte Housing',`<form id="reportForm" class="form-grid"><label>De la<input type="date" name="from" value="${from}"></label><label>Până la<input type="date" name="to" value="${to}"></label><label>Șantier<select name="site"><option value="">Toate șantierele</option>${siteOptions().map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label><label>Locație<select name="location"><option value="">Toate locațiile</option>${state.locations.map(l=>`<option value="${l.id}">${esc(locName(l))}</option>`).join('')}</select></label><label>Persoană<select name="person"><option value="">Toate persoanele</option>${state.people.slice().sort((a,b)=>(a.full_name||'').localeCompare(b.full_name||'')).map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('')}</select></label></form><div id="reportResult" class="report-result"></div>`,'<button class="secondary-btn" id="modalCancel">Închide</button><button class="primary-btn" id="generateReportBtn">Generează raport</button>');$('modalCancel').onclick=closeModal;$('generateReportBtn').onclick=()=>{const f=Object.fromEntries(new FormData($('reportForm')).entries()),a=parse(f.from),b=new Date(parse(f.to).getTime()+DAY);const rows=state.stays.filter(s=>{const u=um[s.unit_id],l=u&&lm[u.location_id];return (!f.site||String(l?.site_id||s.site_id)===String(f.site))&&(!f.location||String(u?.location_id)===String(f.location))&&(!f.person||String(s.person_id)===String(f.person))&&parse(s.check_in_date)<b&&(!s.check_out_date||parse(s.check_out_date)>a)});let nights=0;rows.forEach(s=>{const x=Math.max(a,parse(s.check_in_date)),y=Math.min(b,s.check_out_date?parse(s.check_out_date):b);nights+=Math.max(0,Math.round((y-x)/DAY))});const persons=new Set(rows.map(s=>s.person_id)).size,locations=new Set(rows.map(s=>um[s.unit_id]?.location_id).filter(Boolean)).size,rooms=new Set(rows.map(s=>s.unit_id)).size;$('reportResult').innerHTML=`<div class="report-kpis"><div><b>${rows.length}</b><span>perioade</span></div><div><b>${persons}</b><span>persoane</span></div><div><b>${locations}</b><span>locații</span></div><div><b>${rooms}</b><span>camere</span></div><div><b>${nights}</b><span>nopți totale</span></div></div><p>Raport calculat pentru ${roDate(f.from)} — ${roDate(f.to)}. Datele încheiate rămân incluse în istoric.</p>`}}
