function renderAlertsPage(){const form=$('alertsFilters'),out=$('alertsPageContent'),summary=$('alertsSummary');if(!form||!out||!summary)return;const today=iso(new Date()),pm=Object.fromEntries(state.people.map(p=>[p.id,p])),um=Object.fromEntries(state.units.map(u=>[u.id,u])),lm=Object.fromEntries(state.locations.map(l=>[l.id,l]));const items=[];state.stays.filter(x=>x.check_out_date&&x.check_out_date<today&&!x.archived_at&&!['completed','cancelled'].includes(x.status)).forEach(st=>{const u=um[st.unit_id],l=u&&lm[u.location_id];items.push({type:'expired',severity:'danger',title:'Cazare expirată',person:pm[st.person_id]?.full_name||'Persoană',location:l?locName(l):'—',room:u?.name||'—',date:st.check_out_date,stay:st})});state.units.forEach(u=>{const n=currentActive().filter(s=>String(s.unit_id)===String(u.id)).length,cap=Number(u.capacity||u.beds_count||1);if(n>cap){const l=lm[u.location_id];items.push({type:'capacity',severity:'danger',title:'Capacitate depășită',person:`${n}/${cap} persoane`,location:l?locName(l):'—',room:u.name||'Cameră',date:today})}if(!Number(u.nightly_cost||u.cost_per_night||u.price_per_night||0)&&!activeUnitRate(u)){const l=lm[u.location_id];items.push({type:'rate',severity:'warning',title:'Tarif lipsă',person:'Costul nu poate fi calculat',location:l?locName(l):'—',room:u.name||'Cameră',date:today})}});if(!form.dataset.ready){form.innerHTML=`<label>Tip<select name="type"><option value="">Toate alertele</option><option value="expired">Cazări expirate</option><option value="capacity">Capacitate</option><option value="rate">Tarife lipsă</option></select></label><label>Locație<select name="location"><option value="">Toate locațiile</option>${state.locations.map(l=>`<option>${esc(locName(l))}</option>`).join('')}</select></label><button class="primary-btn" type="submit">Aplică</button>`;form.dataset.ready='1'}const draw=()=>{const f=Object.fromEntries(new FormData(form).entries()),rows=items.filter(x=>(!f.type||x.type===f.type)&&(!f.location||x.location===f.location));summary.innerHTML=[['ALERTE ACTIVE',items.length],['EXPIRATE',items.filter(x=>x.type==='expired').length],['CAPACITATE',items.filter(x=>x.type==='capacity').length],['TARIFE LIPSĂ',items.filter(x=>x.type==='rate').length]].map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('');out.innerHTML=`<table class="data-table history-table"><thead><tr><th>Alertă</th><th>Persoană / detaliu</th><th>Locație</th><th>Cameră</th><th>Data</th><th>Status</th><th>Acțiuni</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.title)}</b></td><td>${esc(x.person)}</td><td>${esc(x.location)}</td><td>${esc(x.room)}</td><td>${roDate(x.date)}</td><td><span class="status-pill ${x.type==='rate'?'planned':'expired'}">${x.type==='rate'?'Atenție':'Critică'}</span></td><td>${x.stay?`<button class="secondary-btn compact-btn" data-alert-edit="${x.stay.id}">Verifică</button>`:'<button class="secondary-btn compact-btn" data-alert-costs>Rezolvă</button>'}</td></tr>`).join('')||'<tr><td colspan="7">Nu există alerte pentru filtrul ales.</td></tr>'}</tbody></table>`;document.querySelectorAll('[data-alert-edit]').forEach(b=>b.onclick=()=>openStayEditor(b.dataset.alertEdit));document.querySelectorAll('[data-alert-costs]').forEach(b=>b.onclick=()=>switchView('finance'))};form.onsubmit=e=>{e.preventDefault();draw()};draw()}


function masterTableConfig(kind){
 const configs={
  people:{title:'Persoane',rows:state.people,cols:[['full_name','Nume'],['company_name','Companie'],['status','Status']],label:r=>r.full_name||'Persoană'},
  sites:{title:'Șantiere',rows:state.sites,cols:[['name','Denumire'],['status','Status']],label:r=>r.name||'Șantier'},
  locations:{title:'Locații',rows:state.locations,cols:[['name','Denumire'],['city','Oraș'],['address','Adresă']],label:r=>locName(r)},
  rooms:{title:'Camere',rows:state.units,cols:[['name','Cameră'],['capacity','Capacitate'],['location_id','Locație']],label:r=>r.name||'Cameră'}
 };return configs[kind]
}
function showMasterData(kind){const c=masterTableConfig(kind);if(!c)return;const lm=Object.fromEntries(state.locations.map(x=>[x.id,x]));const value=(r,k)=>k==='location_id'?locName(lm[r[k]]):r[k]??'—';const canAdd=['sites','people'].includes(kind);showModal(`Administrare · ${c.title}`,`<div class="master-toolbar"><input id="masterSearch" placeholder="Caută în ${c.title.toLowerCase()}"><div class="master-toolbar-actions"><span>${c.rows.length} înregistrări</span>${canAdd?`<button class="primary-btn compact-btn" id="masterAdd">+ Adaugă</button>`:''}</div></div><div class="master-table-wrap"><table class="data-table master-table"><thead><tr>${c.cols.map(x=>`<th>${x[1]}</th>`).join('')}<th></th></tr></thead><tbody id="masterRows"></tbody></table></div><p class="helper-text">Aceste liste sunt sursa comună pentru dropdown-urile din Housing și, ulterior, pentru Site Activities, HR și Assets / Tools.</p>`);const draw=()=>{const q=($('masterSearch')?.value||'').toLowerCase();const rows=c.rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q));$('masterRows').innerHTML=rows.map(r=>`<tr>${c.cols.map(([k])=>`<td>${esc(value(r,k))}</td>`).join('')}<td><button class="secondary-btn compact-btn" data-master-edit="${esc(r.id)}">Editează</button></td></tr>`).join('')||'<tr><td colspan="9">Nu există rezultate.</td></tr>';document.querySelectorAll('[data-master-edit]').forEach(b=>b.onclick=()=>openMasterEditor(kind,b.dataset.masterEdit))};$('masterSearch').oninput=draw;const add=$('masterAdd');if(add)add.onclick=()=>openMasterCreate(kind);draw()}
function openMasterCreate(kind,afterCreate){let fields='',title='Adaugă';if(kind==='sites'){title='Adaugă șantier';fields=`<label>Denumire șantier<input name="name" required placeholder="Ex. HORABACH"></label><label>Status<select name="status"><option value="active">Activ</option><option value="planned">Planificat</option><option value="inactive">Inactiv</option></select></label>`}else if(kind==='people'){title='Adaugă persoană';fields=`<label>Nume complet<input name="full_name" required></label><label>Companie<input name="company_name"></label><label>Status<select name="status"><option value="active">Activ</option><option value="inactive">Inactiv</option></select></label>`}else return;showModal(title,`<form id="masterCreateForm" class="form-grid">${fields}</form>`,'<button class="secondary-btn" id="modalCancel">Anulează</button><button class="primary-btn" id="masterCreateSave">Salvează</button>');$('modalCancel').onclick=closeModal;$('masterCreateSave').onclick=async()=>{const f=Object.fromEntries(new FormData($('masterCreateForm')).entries());try{let created;if(kind==='sites'){if(!f.name?.trim())return toast('Completează denumirea șantierului','error');created=await SiteFlowApi.createSite({name:f.name.trim(),status:f.status||'active',active:f.status!=='inactive'});state.sites.push(created)}else if(kind==='people'){if(!f.full_name?.trim())return toast('Completează numele persoanei','error');created=await SiteFlowApi.createPerson({full_name:f.full_name.trim(),company_name:f.company_name?.trim()||null,status:f.status||'active',active:f.status!=='inactive',person_type:'worker'});state.people.push(created)}fillSites();closeModal();toast('Înregistrarea a fost creată');if(afterCreate)afterCreate(created);else showMasterData(kind)}catch(e){toast(`Nu s-a putut crea: ${e.message}`,'error')}}}
function openMasterEditor(kind,id){const c=masterTableConfig(kind),r=c?.rows.find(x=>String(x.id)===String(id));if(!r)return;let fields='';if(kind==='people')fields=`<label>Nume complet<input name="full_name" value="${esc(r.full_name||'')}"></label><label>Companie<input name="company_name" value="${esc(r.company_name||'')}"></label><label>Status<input name="status" value="${esc(r.status||'active')}"></label>`;if(kind==='sites')fields=`<label>Denumire șantier<input name="name" value="${esc(r.name||'')}"></label><label>Status<select name="status"><option value="active" ${r.status==='active'?'selected':''}>Activ</option><option value="planned" ${r.status==='planned'?'selected':''}>Planificat</option><option value="inactive" ${r.status==='inactive'?'selected':''}>Inactiv</option></select></label>`;if(kind==='locations'){const sites=state.sites.slice().sort((a,b)=>siteName(a).localeCompare(siteName(b),'ro'));fields=`<label>Denumire<input name="name" value="${esc(r.name||'')}"></label><label>Oraș<input name="city" value="${esc(r.city||'')}"></label><label class="full">Șantier<div class="inline-field-action"><select name="site_id"><option value="">— Fără șantier alocat —</option>${sites.map(x=>`<option value="${esc(x.id)}" ${String(r.site_id||r.project_id||'')===String(x.id)?'selected':''}>${esc(siteName(x))}</option>`).join('')}</select><button type="button" class="secondary-btn compact-btn" id="createSiteInline">+ Șantier nou</button></div></label><label class="full">Adresă<input name="address" value="${esc(r.address||'')}"></label>`;}if(kind==='rooms')fields=`<label>Denumire cameră<input name="name" value="${esc(r.name||'')}"></label><label>Capacitate<input type="number" min="1" name="capacity" value="${Number(r.capacity||r.beds_count||1)}"></label>`;showModal(`Editează · ${c.title}`,`<form id="masterEditForm" class="form-grid">${fields}</form>`,'<button class="secondary-btn" id="modalCancel">Anulează</button><button class="primary-btn" id="masterSave">Salvează</button>');$('modalCancel').onclick=closeModal;const createInline=$('createSiteInline');if(createInline)createInline.onclick=()=>openMasterCreate('sites',created=>{openMasterEditor('locations',id);setTimeout(()=>{const sel=document.querySelector('#masterEditForm [name=\"site_id\"]');if(sel)sel.value=created.id},0)});$('masterSave').onclick=async()=>{const f=Object.fromEntries(new FormData($('masterEditForm')).entries());try{let updated;if(kind==='people')updated=await SiteFlowApi.updatePerson(id,f);if(kind==='sites')updated=await SiteFlowApi.updateSite(id,{name:f.name,status:f.status||'active',active:f.status!=='inactive'});if(kind==='locations'){const payload={name:f.name,city:f.city,address:f.address,site_id:f.site_id||null};updated=await SiteFlowApi.updateLocation(id,payload);}if(kind==='rooms')updated=await SiteFlowApi.updateUnit(id,{name:f.name,capacity:Number(f.capacity),beds_count:Number(f.capacity)});if(updated){const arr=kind==='rooms'?state.units:kind==='sites'?state.sites:state[kind];const i=arr.findIndex(x=>String(x.id)===String(id));if(i>=0)arr[i]=updated}closeModal();fillLocations();renderHousing();toast('Înregistrarea a fost actualizată')}catch(e){toast(`Nu s-a putut salva: ${e.message}`,'error')}}}
async function load(){setConnection('Se încarcă…','');try{const data=await SiteFlowApi.loadPlatformData();Object.assign(state,data);fillLocations();renderDashboard();renderHousing();if(state.view==='finance')renderFinancePage();if(state.view==='history')renderHistoryPage();const housed=new Set(currentActive().map(x=>x.person_id));const badge=$('unhousedBadge');if(badge)badge.textContent=state.people.filter(p=>!housed.has(p.id)).length;setConnection('Supabase live','online');toast('Date actualizate')}catch(err){console.error(err);setConnection('Eroare conexiune','error');$('planner').innerHTML=`<div class="planner-empty">Eroare Supabase: ${esc(err.message)}</div>`;showModal('Conexiunea a eșuat',`<p>${esc(err.message)}</p>`)}}
$('todayLabel').textContent=new Date().toLocaleDateString('ro-RO',{weekday:'long',day:'2-digit',month:'long',year:'numeric'});
document.querySelectorAll('.nav-link[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));document.querySelector('.nav-parent').onclick=e=>{document.querySelector('[data-group="housing"]').classList.toggle('open');switchView('housing')};document.querySelectorAll('[data-open-housing]').forEach(b=>b.onclick=()=>switchView('housing'));document.querySelectorAll('.locked,.locked-card').forEach(b=>b.onclick=()=>showModal(b.dataset.moduleName,`<p>Modulul <b>${esc(b.dataset.moduleName)}</b> va folosi aceeași bază de date, aceleași persoane, șantiere și roluri SiteFlow.</p>`));document.querySelectorAll('.nav-child').forEach(b=>b.onclick=()=>{switchView('housing');const section=b.dataset.section;document.querySelectorAll('.nav-child').forEach(x=>x.classList.toggle('active',x===b));if(section==='locations'||section==='rooms'){state.tab='rooms';renderCurrentTab();return}if(section==='active'||section==='planned'||section==='expired'){state.tab='list';state.status=section==='planned'?'planned':section==='active'?'active':'';renderHousing();if(section==='expired'){const today=iso(new Date());setTimeout(()=>{const rows=[...document.querySelectorAll('#stayList tbody tr')];rows.forEach(r=>{const id=r.querySelector('[data-stay-menu]')?.dataset.stayMenu,stay=state.stays.find(x=>String(x.id)===String(id));r.style.display=stay&&stay.check_out_date<=today&&!stay.archived_at?'':'none'})},0)}return}if(section==='planner'){state.tab='planner';state.status='';renderHousing();return}if(section==='dashboard'){switchView('dashboard');return}if(section==='reports'){showReports();return}if(section==='costs'){switchView('finance');toast('Costuri și facturare deschise');return}if(section==='movements'){showMovementReport();return}if(section==='history'){switchView('history');return}if(section==='unhoused'){showUnhoused();return}if(section==='alerts'){showAlerts();return}if(section==='settings'){switchView('settings');return}const titles={};showModal(titles[section]||'Housing',`<p>Secțiunea <b>${esc(titles[section]||section)}</b> nu are elemente de afișat.</p>`)});document.querySelectorAll('[data-housing-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.housingTab;renderCurrentTab()});
$('menuToggle').onclick=()=>{$('sidebar').classList.add('open');$('mobileBackdrop').classList.add('show')};$('themeToggle').onclick=toggleTheme;applyTheme(localStorage.getItem('siteflow-theme')||'light');$('mobileBackdrop').onclick=closeMenu;$('refreshBtn').onclick=load;$('newStayBtn').onclick=()=>openNewStay();const filterToggle=$('filterToggle');if(filterToggle)filterToggle.onclick=()=>$('filterDrawer').classList.toggle('open');$('locationFilter').onchange=e=>{state.location=e.target.value;renderHousing()};$('siteFilter').onchange=e=>{state.site=e.target.value;renderHousing()};$('statusFilter').onchange=e=>{state.status=e.target.value;renderHousing()};$('daysFilter').onchange=e=>{state.days=Number(e.target.value);renderHousing()};$('onlyAvailable').onchange=e=>{state.onlyAvailable=e.target.checked;renderHousing()};$('globalSearch').oninput=e=>{state.search=e.target.value;if(state.view==='housing')renderCurrentTab()};$('startDate').onchange=e=>{state.start=parse(e.target.value);renderHousing()};$('prevBtn').onclick=()=>{state.start=new Date(state.start.getTime()-state.days*DAY);renderHousing()};$('nextBtn').onclick=()=>{state.start=new Date(state.start.getTime()+state.days*DAY);renderHousing()};$('todayBtn').onclick=()=>{state.start=new Date();state.start.setHours(0,0,0,0);state.start.setDate(state.start.getDate()-Math.min(3,state.days-1));renderHousing()};$('resetFilters').onclick=()=>{state.location='';state.site='';state.status='';state.search='';state.days=14;state.onlyAvailable=false;$('globalSearch').value='';fillLocations();renderHousing()};$('modalClose').onclick=closeModal;$('modalBackdrop').onclick=e=>{if(e.target===$('modalBackdrop'))closeModal()};$('adminBtn').onclick=()=>showModal('Administrare SiteFlow','<p>Zona SISTEM din meniul stâng este sursa comună de date pentru toate modulele: Persoane, Companii, Șantiere, Utilizatori și roluri. Locațiile și camerele se gestionează în Housing → Configurare.</p>');$('profileBtn').onclick=()=>showModal('Profil administrator','<div class="detail-grid"><span>Rol</span><b>Administrator</b><span>Platformă</span><b>SiteFlow</b></div>');document.addEventListener('click',e=>{if(!e.target.closest('#contextMenu')&&!e.target.closest('[data-stay-menu]')&&!e.target.closest('[data-room-menu]'))$('contextMenu').classList.add('hidden')});

document.querySelectorAll('.sidebar-section-toggle').forEach(b=>b.onclick=()=>b.closest('.sidebar-section').classList.toggle('open'));
document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{const q=b.dataset.quick;if(q==='expired'){state.tab='list';state.status='';renderHousing();toast('Sunt evidențiate cazări cu data de plecare depășită');return}if(q==='unhoused'){document.querySelector('[data-section="unhoused"]')?.click();return}if(q==='checkins'||q==='checkouts'){document.querySelector('[data-section="movements"]')?.click();return}if(q==='free'){state.onlyAvailable=true;renderHousing();return}});
document.addEventListener('click',e=>{
  const costTrigger=e.target.closest('#dashboardOpenCosts,#costsShortcut,[data-open-costs],.mini-cost-card');
  if(costTrigger){e.preventDefault();e.stopPropagation();switchView('finance');return}
  const moduleCard=e.target.closest('.module-card');
  if(moduleCard?.classList.contains('housing-card')){switchView('housing');return}
});
document.addEventListener('click',e=>{const card=e.target.closest('[data-metric-action]');if(!card)return;const a=card.dataset.metricAction;switchView('housing');if(a==='rooms'){state.tab='rooms';state.status='';state.onlyAvailable=false}else if(a==='active'){state.tab='list';state.status='active';state.onlyAvailable=false}else if(a==='planner'){state.tab='planner';state.status='';state.onlyAvailable=false}else if(a==='free'){state.tab='rooms';state.status='';state.onlyAvailable=true}else if(a==='checkins'||a==='checkouts'){document.querySelector('[data-section="movements"]')?.click();return}renderHousing()});
