const settingsBtn=$('plannerSettingsBtn');if(settingsBtn)settingsBtn.onclick=()=>{const s=state.plannerSettings;showModal('Setări planner',`<div class="settings-list"><label><input type="checkbox" id="showCompleted" ${s.showCompleted?'checked':''}> Afișează cazări încheiate</label><label><input type="checkbox" id="showWeekends" ${s.showWeekends?'checked':''}> Evidențiază weekendurile</label><label><input type="checkbox" id="showDatesOnBars" ${s.showDates?'checked':''}> Afișează datele pe benzi</label><label><input type="checkbox" id="compactPlanner" ${s.compact?'checked':''}> Rânduri compacte</label></div>`,'<button class="secondary-btn" id="modalCancel">Anulează</button><button class="primary-btn" id="savePlannerSettings">Salvează</button>');$('modalCancel').onclick=closeModal;$('savePlannerSettings').onclick=()=>{state.plannerSettings={showCompleted:$('showCompleted').checked,showWeekends:$('showWeekends').checked,showDates:$('showDatesOnBars').checked,compact:$('compactPlanner').checked};localStorage.setItem('siteflow-planner-settings',JSON.stringify(state.plannerSettings));document.body.classList.toggle('compact-planner',state.plannerSettings.compact);closeModal();renderHousing();toast('Setările plannerului au fost salvate')}};document.body.classList.toggle('compact-planner',state.plannerSettings.compact);
const zoomIn=$('zoomInBtn'),zoomOut=$('zoomOutBtn');function applyZoom(){state.zoom=Math.max(.65,Math.min(2,state.zoom));const l=$('zoomLabel');if(l)l.textContent=`${Math.round(state.zoom*100)}%`;if(state.tab==='planner')renderPlanner()}if(zoomIn)zoomIn.onclick=()=>{state.zoom+=.15;applyZoom()};if(zoomOut)zoomOut.onclick=()=>{state.zoom-=.15;applyZoom()};const compactBtn=$('compactRowsBtn');if(compactBtn)compactBtn.onclick=()=>{state.plannerSettings.compact=!state.plannerSettings.compact;document.body.classList.toggle('compact-planner',state.plannerSettings.compact);localStorage.setItem('siteflow-planner-settings',JSON.stringify(state.plannerSettings));renderHousing()};
const adminMap={adminPeople:'people',adminSites:'sites'};Object.entries(adminMap).forEach(([id,kind])=>{const el=$(id);if(el)el.onclick=()=>showMasterData(kind)});const adminCompanies=$('adminCompanies');if(adminCompanies)adminCompanies.onclick=()=>showModal('Companii','<p>Companiile vor fi centralizate aici ca sursă comună pentru toate modulele SiteFlow.</p>');['adminUsers','adminRoles'].forEach(id=>{const el=$(id);if(el)el.onclick=()=>showModal(el.textContent.trim(),'<p>Secțiunea va fi conectată la autentificarea și permisiunile comune SiteFlow.</p>')});
function initSidebarResize(){const sidebar=$('sidebar'),handle=$('sidebarResizer');if(!sidebar||!handle)return;const saved=Number(localStorage.getItem('siteflow-sidebar-width'));if(saved)document.documentElement.style.setProperty('--sidebar-width',`${Math.max(220,Math.min(430,saved))}px`);let active=false;handle.onpointerdown=e=>{if(window.innerWidth<=900)return;active=true;handle.setPointerCapture?.(e.pointerId);document.body.classList.add('resizing-sidebar');e.preventDefault()};handle.onpointermove=e=>{if(!active)return;const w=Math.max(220,Math.min(430,e.clientX));document.documentElement.style.setProperty('--sidebar-width',`${w}px`);localStorage.setItem('siteflow-sidebar-width',String(w))};const stop=()=>{active=false;document.body.classList.remove('resizing-sidebar')};handle.onpointerup=stop;handle.onpointercancel=stop}
